 impl VerusVerifyVisitor {
     fn add_verus_spec_if_needed(&self, attrs: &mut Vec<syn::Attribute>, span: proc_macro2::Span) {
         if !self.verify_const || get_verus_spec(attrs).is_some() {
             return;
