109. pub(crate) fn rewrite_verus_attribute(
110.     erase: &EraseGhost,
111.     attr_args: proc_macro::TokenStream,
112.     input: proc_macro::TokenStream,
113. ) -> proc_macro::TokenStream {
114.     if !erase.keep() {
115.         return input;
116.     }
117. 
118.     let mut item = syn::parse_macro_input!(input as Item);
119.     let args = syn::parse_macro_input!(attr_args with syn::punctuated::Punctuated::<syn::Meta, syn::Token![,]>::parse_terminated);
120. 
121.     let mut attributes = Vec::new();
122.     let mut contains_non_external = false;
123.     let mut contains_external = false;
124.     let mut spec_fun = None;
125.     const VERIFY_ATTRS: [&str; 4] = ["rlimit", "spinoff_prover", "external_derive", "ext_equal"];
126.     const DUAL_ATTR: &str = "dual_spec";
127.     const IGNORE_VERIFY_ATTRS: [&str; 3] =
128.         ["external", "external_body", "external_type_specification"];
129.     // Modifier attrs are compatible with both external and non-external attrs.
130.     // They neither set contains_external nor contains_non_external.
131.     const MODIFIER_ATTRS: [&str; 3] = [
132.         "reject_recursive_types",
133.         "reject_recursive_types_in_ground_variants",
134.         "accept_recursive_types",
135.     ];
136. 
137.     for arg in &args {
138.         let path = arg.path().get_ident().expect("Invalid verus verifier attribute");
139.         if IGNORE_VERIFY_ATTRS.contains(&path.to_string().as_str()) {
140.             contains_external = true;
141.             attributes.push(quote_spanned!(arg.span() => #[verifier::#arg]));
142.         } else if VERIFY_ATTRS.contains(&path.to_string().as_str()) {
143.             contains_non_external = true;
144.             attributes.push(quote_spanned!(arg.span() => #[verifier::#arg]));
145.         } else if MODIFIER_ATTRS.contains(&path.to_string().as_str()) {
146.             attributes.push(quote_spanned!(arg.span() => #[verifier::#arg]));
147.         } else if DUAL_ATTR == path.to_string().as_str() {
148.             // This is a macro-level hack to support dual mode.
149.             // Thus, only a limited number of pure compute functions are
150.             // supported.
151.             // The real dual mode is not ready yet (e.g., verifier::dual_spec).
152.             // The spec function is generated with the name _VERUS_SPEC_<name>
153.             // if no name is given.
154.             if let syn::Item::Fn(f) = &mut item {
155.                 let mut spec_f = f.clone();
156.                 let ident = if let syn::Meta::List(list) = arg {
157.                     syn::parse2(list.tokens.clone())
158.                         .expect("unsupported tokens in verus_verify(dual_spec(...))")
159.                 } else {
160.                     syn::Ident::new(
161.                         &format!("{DUAL_SPEC_PREFIX}_{}", f.sig.ident),
162.                         f.sig.ident.span(),
163.                     )
164.                 };
165.                 spec_f.sig.ident = ident.clone();
166.                 spec_f.attrs = vec![mk_verus_attr_syn(f.span(), quote! { spec })];
167.                 // remove proof-related macros
168.                 replace_block(EraseGhost::Erase, spec_f.block_mut().unwrap(), false);
169.                 spec_fun = Some(spec_f);
170. 
171.                 attributes
172.                     .push(quote_spanned!(arg.span() => #[verifier::when_used_as_spec(#ident)]));
173.             }
174.         } else {
175.             let span = arg.span();
176.             return proc_macro::TokenStream::from(quote_spanned!(span =>
177.                 compile_error!("unsupported parameters {:?} in #[verus_verify(...)]", arg);
178.             ));
179.         }
180.     }
181.     if contains_external && contains_non_external {
182.         return proc_macro::TokenStream::from(quote_spanned!(args.span() =>
183.             compile_error!("conflict parameters in #[verus_verify(...)]");
184.         ));
185.     }
186.     if !contains_external {
187.         attributes.push(quote_spanned!(item.span() => #[verifier::verify]));
188.     }
189. 
190.     // Special handling for impl blocks, add marker attribute to each method for `#[verus_spec]`.
191.     let mut visitor = VerusVerifyVisitor { verify_const: true };
192.     visitor.visit_item_mut(&mut item);
193.     let mut new_stream = quote_spanned! {item.span()=>
194.         #(#attributes)*
195.         #item
196.     };
197.     spec_fun.map(|f| f.to_tokens(&mut new_stream));
198.     new_stream.into()
199. }
